from __future__ import annotations

from datetime import date
import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LiquidityScreenedEqualWeighting(Strategy):
    rationale = (
        "This strategy exploits the outperformance of small-cap stocks with high liquidity. "
        "By ranking and selecting the most liquid equities within a small-cap segment, we aim to "
        "capitalize on lower bid-ask spreads and greater market participation."
    )

    def __init__(self, window: int = 30, top_n: int = 30) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty() or history.height < self._window * len(view.symbols):
            return Signal(information_available_at=stamp, weights={})

        liquidity = (
            history.lazy()
            .group_by("symbol")
            .agg(
                (pl.col("volume").sum() / self._window).alias("avg_volume"),
            )
            .select(["symbol", "avg_volume"])
            .collect()
        )

        symbols = [s for s in view.symbols if s in liquidity.columns]
        if not symbols:
            return Signal(information_available_at=stamp, weights={})

        liquidity_filtered = (
            liquidity.filter(pl.col("symbol").is_in(symbols))
            .sort(
                pl.col("avg_volume"),
                descending=True,
            )
            .head(self._top_n)
        )

        weights = {s: 1.0 / self._top_n for s in liquidity_filtered["symbol"]}
        return Signal(information_available_at=stamp, weights=weights)


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible.select("session_date").max().item()
    assert isinstance(newest, date)
    return newest
